partial class QuotaWidget {
    // Settings use neutral office surfaces independently of the floating-window palette.
    static bool? settingsDarkOverride=null;
    static readonly bool systemSettingsDark=DetectSettingsDark();
    static bool DetectSettingsDark() {
        try {var value=Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize","AppsUseLightTheme",1);return value!=null && Convert.ToInt32(value)==0;}
        catch(Exception) {return false;}
    }
    static readonly string[] SettingRoles={"Background","Surface","Text","Secondary","Line","Input","Accent","Selected","Guide","OnAccent","Danger"};
    static Brush SettingsBrush(string role) {
        string[] colors=(settingsDarkOverride ?? systemSettingsDark)
            ? new[]{"#20242A","#292E36","#EEF1F5","#ACB6C3","#414A56","#242A32","#8FB5E9","#354761","#EFB77E","#202C3E","#EF8087"}
            : new[]{"#F7F8FA","#FFFFFF","#27313C","#596776","#DFE4E9","#FFFFFF","#315F98","#EAF0F8","#A55320","#FFFFFF","#CB4149"};
        return new SolidColorBrush((Color)ColorConverter.ConvertFromString(colors[Array.IndexOf(SettingRoles,role)]));
    }
    static Grid InlineSettingsRow(TextBlock label,Grid row) {
        row.ColumnDefinitions[1].Width=new GridLength(44);row.ColumnDefinitions[2].Width=new GridLength(20);
        row.ColumnDefinitions.Insert(0,new ColumnDefinition {Width=new GridLength(104)});
        foreach(UIElement child in row.Children) Grid.SetColumn(child,Grid.GetColumn(child)+1);
        label.Margin=new Thickness(0);label.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(label);
        row.Margin=new Thickness(0,0,0,5);
        foreach(var child in row.Children) {
            var box=child as TextBox;if(box!=null) box.Padding=new Thickness(5,3,5,3);
            var slider=child as Slider;if(slider!=null) slider.Margin=new Thickness(0,0,8,0);
        }
        return row;
    }
    static Border SettingsGroup(TextBlock heading,UIElement[] elements) {
        heading.Foreground=SettingsBrush("Secondary");heading.FontSize=12;heading.FontWeight=FontWeights.SemiBold;heading.Margin=new Thickness(0,0,0,6);
        var content=new StackPanel {Margin=new Thickness(8)};content.Children.Add(heading);
        foreach(var element in elements) content.Children.Add(element);
        return new Border {Background=SettingsBrush("Surface"),BorderBrush=SettingsBrush("Line"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(5),Margin=new Thickness(0,0,0,6),Child=content};
    }
    static void SaveSettingsSnapshot(Window dialog,string name) {
        var bitmap=new RenderTargetBitmap((int)Math.Ceiling(dialog.ActualWidth),(int)Math.Ceiling(dialog.ActualHeight),96,96,PixelFormats.Pbgra32);
        bitmap.Render(dialog);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));
        using(var output=File.Create(Path.Combine(Path.GetDirectoryName(settingsFocusedReport),name))) encoder.Save(output);
    }
